diffs.patch:
Index: site/src/pages/words-of-the-day/practice.astro
===================================================================
--- site/src/pages/words-of-the-day/practice.astro	
+++ site/src/pages/words-of-the-day/practice.astro	
@@ -1,2265 +1,2269 @@
 ---
 import LexiconPracticeMount from "../../lexicon/LexiconPracticeMount.astro";
 import CourseLayout from "../../layouts/CourseLayout.astro";

 const frontmatter = {
   title: "Практика — Слова дня",
   description: "Інтервальне повторення слів вашого рівня (CEFR) з локальним прогресом у браузері.",
 };
 ---

 <CourseLayout
   title={frontmatter.title}
   description={frontmatter.description}
   currentPath="/words-of-the-day/practice/"
   heroVariant="lexicon"
   wide
   showHero={false}
 >
   <main class="word-atlas lexicon-practice-page" data-word-atlas>
     <LexiconPracticeMount />
   </main>
 </CourseLayout>

 <style>
   .lexicon-practice-page {
     max-width: 1120px;
     margin: 0 auto;
     padding: 0.5rem 1.5rem 3.5rem;
   }

   @media (max-width: 760px) {
     .lexicon-practice-page {
       padding: 0.5rem 1rem 3rem;
     }
   }

   .lexicon-practice-badge {
     display: inline-flex;
     align-items: center;
     min-height: 1.75rem;
     padding: 0 0.65rem;
     border-radius: 4px;
     background: var(--lu-state-active);
     color: var(--lu-primary);
     font-size: 0.78rem;
     font-weight: 900;
     letter-spacing: 0.04em;
     text-transform: uppercase;
   }

   :global(.lexicon-practice) {
     display: grid;
     gap: 1.25rem;
     color: var(--lu-text);
   }

   :global(.lexicon-practice-toolbar) {
     display: flex;
     flex-wrap: wrap;
     align-items: end;
     justify-content: space-between;
     gap: 1rem;
     padding-bottom: 1rem;
     border-bottom: 1px solid var(--lu-border);
   }

   :global(.lexicon-practice-toolbar h2) {
     margin: 0;
     font-size: 1.45rem;
     line-height: 1.2;
   }

   :global(.lexicon-practice-status) {
     min-height: 1.4rem;
     margin: 0.35rem 0 0;
     color: var(--lu-text-muted);
   }

   :global(.lexicon-practice-modes),
   :global(.lexicon-practice-levels-row),
   :global(.lexicon-rating-bar) {
     display: flex;
     flex-wrap: wrap;
     align-items: center;
     gap: 0.5rem;
   }

   :global(.lexicon-practice-levels) {
     margin: 1.25rem 0 0;
   }

   :global(.lexicon-practice-levels-label) {
     font-size: 0.78rem;
     font-weight: 900;
     letter-spacing: 0.04em;
     text-transform: uppercase;
     color: var(--lu-text-muted);
     margin-right: 0.35rem;
   }

   :global(.lexicon-practice-levels-hint) {
     margin: 0.5rem 0 0;
     font-size: 0.85rem;
   }

   :global(.lexicon-practice button) {
     /* P0-8: raised from the 44px AA floor to the 48px target-size floor. */
     min-height: 48px;
     border: 1px solid var(--lu-border);
     border-radius: 6px;
     background: var(--lu-surface);
     color: var(--lu-text);
     font: inherit;
     font-weight: 800;
     cursor: pointer;
   }

   :global(.lexicon-practice button:disabled) {
     cursor: wait;
     opacity: 0.7;
   }

   :global(.lexicon-practice button:hover),
   :global(.lexicon-practice button:focus-visible),
   :global(.lexicon-practice-stage:focus-visible),
   :global(.lexicon-cloze-row input:focus-visible) {
     border-color: var(--lu-primary);
     outline: 2px solid var(--lu-primary);
     outline-offset: 2px;
     box-shadow: 0 0 0 3px var(--lu-state-active);
   }

   :global(.lexicon-practice-modes button),
   :global(.lexicon-practice-levels-row button),
   :global(.lexicon-rating-bar button),
   :global(.lexicon-practice-start button) {
     padding: 0 0.85rem;
   }

   :global(.lexicon-practice-modes button.active),
   :global(.lexicon-practice-levels-row button.active) {
     border-color: var(--lu-primary);
     background: var(--lu-primary);
     color: var(--lu-on-primary);
   }

   :global(.lexicon-practice-stage) {
     display: grid;
     gap: 1rem;
     max-width: 760px;
     border-radius: 8px;
   }

   :global(.lexicon-rating-bar) {
     justify-content: center;
   }

   :global(.lexicon-choice),
   :global(.lexicon-cloze),
   :global(.lexicon-paronym) {
     display: grid;
     gap: 1rem;
   }

   :global(.lexicon-choice-prompt),
   :global(.lexicon-cloze-translation) {
     margin: 0;
     color: var(--lu-text);
     font-size: 1.15rem;
     font-weight: 850;
     line-height: 1.45;
   }
   :global(.lexicon-cloze-attribution) {
     margin: -0.45rem 0 0;
     color: var(--lu-text-muted);
     font-size: 0.82rem;
     line-height: 1.35;
   }
   :global(.lexicon-cloze-attribution a) {
     color: inherit;
     text-decoration-thickness: 1px;
     text-underline-offset: 0.18em;
   }

   :global(.lexicon-option-list) {
     display: grid;
     grid-template-columns: repeat(2, minmax(0, 1fr));
     gap: 0.65rem;
     margin: 0;
     padding: 0;
     list-style: none;
   }

   :global(.lexicon-option-list button) {
     width: 100%;
     padding: 0.65rem 0.85rem;
     text-align: left;
   }

   :global(.lexicon-cloze-row) {
     display: flex;
     flex-wrap: wrap;
     align-items: center;
     gap: 0.5rem;
     font-size: 1.1rem;
     line-height: 1.5;
   }

   :global(.lexicon-cloze-row input) {
     min-width: 11rem;
     min-height: 44px;
     padding: 0.45rem 0.65rem;
     border: 1px solid var(--lu-border);
     border-radius: 6px;
     background: var(--lu-surface);
     color: var(--lu-text);
     font: inherit;
     font-size: 16px;
   }

   :global(.lexicon-cloze-feedback) {
     margin: 0;
     padding: 0.75rem 0.9rem;
     border-radius: 8px;
     font-weight: 800;
     line-height: 1.45;
   }

   :global(.lexicon-cloze-feedback.correct) {
     background: var(--lu-state-correct-bg);
     color: var(--lu-state-correct-fg);
   }

   :global(.lexicon-cloze-feedback.case-miss) {
     background: var(--lu-state-missed);
     color: var(--lu-orange);
   }

   :global(.lexicon-cloze-feedback.wrong-word) {
     background: var(--lu-state-wrong-bg);
     color: var(--lu-state-wrong-fg);
   }

   :global(.lexicon-practice-muted),
   :global(.lexicon-practice-warning) {
     margin: 0;
     color: var(--lu-text-muted);
     line-height: 1.55;
   }

   :global(.lexicon-practice-warning) {
     color: var(--lu-state-wrong-fg);
   }

   :global(.lexicon-practice .sr-only) {
     position: absolute;
     width: 1px;
     height: 1px;
     padding: 0;
     margin: -1px;
     overflow: hidden;
     clip: rect(0, 0, 0, 0);
     white-space: nowrap;
     border: 0;
   }

   /* P0-2: every active-phase empty state gets the same shape — one sentence,
      a primary next-action button, and (where honest) real-count secondary modes. */
   :global(.practice-empty-state) {
     display: grid;
     gap: 0.75rem;
     justify-items: start;
   }

   :global(.practice-empty-primary) {
     width: 100%;
   }

   :global(.practice-empty-secondary) {
     display: flex;
     flex-wrap: wrap;
     gap: 0.5rem;
   }

   @media (max-width: 760px) {
     .lexicon-practice-page {
       padding: 2.5rem 1rem 3.5rem;
     }

     :global(.lexicon-option-list) {
       grid-template-columns: 1fr;
     }

     :global(.lexicon-practice-toolbar) {
       align-items: stretch;
     }

     :global(.lexicon-cloze-row) {
       align-items: stretch;
     }

     :global(.lexicon-cloze-row input),
     :global(.lexicon-cloze-row button) {
       width: 100%;
     }
   }
   .lexicon-practice-back {
     display: inline-flex;
     align-items: center;
     justify-content: center;
     min-height: 44px;
     margin-bottom: 0.7rem;
     padding: 0 0.85rem;
     border: 1px solid var(--lu-border);
     border-radius: 8px;
     background: var(--lu-surface);
     color: var(--lu-text);
     font-size: 0.9rem;
     font-weight: 900;
     text-decoration: none;
   }

   .lexicon-practice-back:hover,
   .lexicon-practice-back:focus-visible {
     border-color: var(--lu-primary);
     color: var(--lu-primary);
     outline: none;
     box-shadow: 0 0 0 3px var(--lu-state-active);
   }

   :global(.lexicon-practice-status) {
     min-height: 1.4rem;
     margin: 0 0 0.65rem;
     color: var(--lu-text-muted);
     font-weight: 800;
   }

   :global(.lexicon-practice-home) {
     display: grid;
     gap: 1.25rem;
   }

   :global(.lexicon-practice-stage-shell) {
     max-width: 760px;
     margin: 0 auto;
     padding-top: 0.4rem;
   }

   :global(.lexicon-practice-stage-bar) {
     display: flex;
     flex-wrap: wrap;
     align-items: center;
     gap: 12px;
     padding-bottom: 1rem;
     margin-bottom: 1.4rem;
     border-bottom: 1px solid var(--lu-border);
   }

   :global(.lexicon-practice-stage-bar h2) {
     margin: 0;
     color: var(--lu-text);
     font-size: 1.4rem;
   }

   :global(.stage-back) {
     display: inline-flex;
     align-items: center;
     justify-content: center;
     gap: 6px;
     min-height: 44px;
     padding: 0 12px;
     border: 1px solid var(--lu-border);
     border-radius: 8px;
     background: var(--lu-surface);
     color: var(--lu-text);
     font: inherit;
     font-weight: 900;
   }

   :global(.stage-back:hover),
   :global(.stage-back:focus-visible) {
     border-color: var(--lu-primary);
     color: var(--lu-primary);
     outline: none;
     box-shadow: 0 0 0 3px var(--lu-state-active);
   }

   :global(.queue-pill) {
     display: inline-flex;
     align-items: center;
     min-height: 44px;
     margin-left: auto;
     padding: 0 12px;
     border: 1px solid var(--lu-border);
     border-radius: 999px;
     background: var(--lu-surface-muted);
     color: var(--lu-text-muted);
     font-size: 0.82rem;
     font-weight: 900;
   }

   /*
    * D6: Далі/Next moves into the top status row, immediately right of the n/N
    * pill, so it is reachable without scrolling at 1366x768 and 390x844 — the
    * bottom advance button (below the exercise card, off the first viewport on
    * long prompts) is gone; exactly one Next control per round.
    */
   :global(.queue-next-btn) {
     display: inline-flex;
     align-items: center;
     justify-content: center;
     gap: 6px;
     min-height: 44px;
     padding: 0 16px;
     border-radius: 999px;
     font-weight: 900;
   }

   :global(.lexicon-practice-stage) {
     display: grid;
     gap: 1.1rem;
     max-width: 760px;
     border-radius: 12px;
   }

   :global(.lexicon-practice-stage .flashcards) {
     margin: 0;
   }

   :global(.lexicon-practice-stage .flashcard) {
     width: 100%;
     max-width: 100%;
     height: 300px;
     min-height: 300px;
   }

   :global(.lexicon-practice-stage .flashcard-inner),
   :global(.lexicon-practice-stage .flashcard-front),
   :global(.lexicon-practice-stage .flashcard-back) {
     border-radius: 18px;
   }

   :global(.lexicon-practice-stage .flashcard-front),
   :global(.lexicon-practice-stage .flashcard-back) {
     box-sizing: border-box;
     min-height: 300px;
     overflow-x: hidden;
     overflow-y: auto;
     padding: clamp(1rem, 4vw, 2rem);
   }

   :global(.lexicon-practice-stage .flashcard-word) {
     display: block;
     min-width: 0;
     max-width: 100%;
     color: var(--lu-text);
     font-size: clamp(1.35rem, 4.2vw, 2.4rem);
     font-weight: 900;
     line-height: 1.15;
     overflow-wrap: anywhere;
     word-break: break-word;
     text-align: center;
   }

   :global(.flashcard-flip-hint) {
     display: block;
     margin-top: 0.6rem;
     color: var(--lu-text-muted);
     font-size: 0.85rem;
     font-weight: 700;
   }

   :global(.flashcard-back-tags) {
     display: flex;
     flex-wrap: wrap;
     align-items: center;
     justify-content: center;
     gap: 0.35rem;
     margin-top: 0.35rem;
   }

   :global(.flashcard-heritage-chip) {
     display: inline-flex;
     align-items: center;
     padding: 0.15rem 0.55rem;
     border: 2px solid rgba(255, 255, 255, 0.7);
     border-radius: 999px;
     background: rgba(255, 255, 255, 0.12);
     color: inherit;
     font-size: 0.72rem;
     font-weight: 800;
     letter-spacing: 0.01em;
   }

   :global(.rating-bar) {
     display: grid;
     grid-template-columns: repeat(4, minmax(0, 1fr));
     gap: 0.6rem;
     margin-top: 1.3rem;
   }

   :global(.rating-bar-hint) {
     grid-column: 1 / -1;
     margin: 0 0 0.2rem;
     color: var(--lu-text-muted);
     font-size: 0.85rem;
     font-weight: 700;
   }

   :global(.rate-btn) {
     display: flex;
     min-height: 58px;
     flex-direction: column;
     align-items: center;
     gap: 3px;
     padding: 8px 6px;
     border-radius: 12px;
   }

   :global(.rate-btn:hover) {
     transform: translateY(-2px);
   }

   :global(.rate-btn .rk) {
     color: var(--lu-text-muted);
     font-size: 0.72rem;
     font-weight: 900;
   }

   :global(.rate-btn .rt) {
     font-size: 0.98rem;
     font-weight: 900;
   }

   /*
    * Opus P0-5: these four colors used to exist on :hover only, so at rest (and on
    * touch, where there is no hover) Again/Hard/Good/Easy were visually identical
    * grey boxes. The border color is now a base-state channel; hover/focus only
    * add the stronger tint on top of it.
    */
   :global(.rate-btn[data-rate="again"]) {
     border-color: var(--lu-red);
   }

   :global(.rate-btn[data-rate="hard"]) {
     border-color: var(--lu-orange);
   }

   :global(.rate-btn[data-rate="good"]) {
     border-color: var(--lu-green);
   }

   :global(.rate-btn[data-rate="easy"]) {
     border-color: var(--lu-blue);
   }

   :global(.rate-btn[data-rate="again"]:hover),
   :global(.rate-btn[data-rate="again"]:focus-visible) {
     background: var(--lu-red-light);
   }

   :global(.rate-btn[data-rate="hard"]:hover),
   :global(.rate-btn[data-rate="hard"]:focus-visible) {
     background: var(--lu-orange-light);
   }

   :global(.rate-btn[data-rate="good"]:hover),
   :global(.rate-btn[data-rate="good"]:focus-visible) {
     background: var(--lu-green-light);
   }

   :global(.rate-btn[data-rate="easy"]:hover),
   :global(.rate-btn[data-rate="easy"]:focus-visible) {
     background: var(--lu-blue-light);
   }

   :global(.lexicon-choice),
   :global(.lexicon-cloze),
   :global(.lexicon-heritage),
   :global(.lexicon-paronym) {
     display: grid;
     gap: 1rem;
   }

   :global(.heritage-task) {
     margin: 0 0 -0.1rem;
     color: var(--lu-teal);
     font-size: 0.92rem;
     font-weight: 900;
   }

   :global(.heritage-sentence) {
     margin: 0;
     padding: 1.4rem 1.5rem;
     border: 1px solid var(--lu-border);
     border-left: 4px solid var(--lu-teal);
     border-radius: 14px;
     background: var(--lu-surface-raised);
     box-shadow: var(--lu-shadow);
     color: var(--lu-text);
     font-size: 1.45rem;
     font-weight: 700;
     line-height: 1.6;
   }

   :global(.heritage-slot) {
     display: inline-flex;
     align-items: center;
     justify-content: center;
     min-width: 96px;
     padding: 0 10px;
     margin: 0 4px;
     border-bottom: 3px solid var(--lu-teal);
     color: var(--lu-teal);
     font-weight: 900;
   }

   :global(.heritage-slot.filled) {
     border-bottom-color: var(--lu-green);
     color: var(--lu-state-correct-fg);
   }

   :global(.heritage-feedback) {
     margin: 0;
     padding: 0.85rem 0.95rem;
     border-radius: 8px;
     font-weight: 800;
     line-height: 1.45;
   }

   :global(.heritage-feedback p) {
     margin: 0;
   }

   :global(.heritage-feedback p + p) {
     margin-top: 0.35rem;
   }

   :global(.heritage-feedback.correct) {
     background: var(--lu-state-correct-bg);
     color: var(--lu-state-correct-fg);
   }

   :global(.heritage-feedback.calque) {
     border: 1px solid color-mix(in srgb, var(--lu-orange) 40%, transparent);
     background: var(--lu-orange-light);
     color: var(--lu-orange);
   }

   :global(.heritage-feedback.wrong) {
     background: var(--lu-state-wrong-bg);
     color: var(--lu-state-wrong-fg);
   }

   :global(.heritage-citation) {
     color: var(--lu-text-muted);
     font-size: 0.86rem;
     font-weight: 700;
   }

   :global(.paronym-task) {
     margin: 0 0 -0.1rem;
     color: var(--lu-purple);
     font-size: 0.92rem;
     font-weight: 900;
   }

   :global(.paronym-sentence) {
     margin: 0;
     padding: 1.4rem 1.5rem;
     border: 1px solid var(--lu-border);
     border-left: 4px solid var(--lu-purple);
     border-radius: 14px;
     background: var(--lu-surface-raised);
     box-shadow: var(--lu-shadow);
     color: var(--lu-text);
     font-size: 1.45rem;
     font-weight: 700;
     line-height: 1.6;
   }

   :global(.paronym-slot) {
     display: inline-flex;
     align-items: center;
     justify-content: center;
     min-width: 96px;
     padding: 0 10px;
     margin: 0 4px;
     border-bottom: 3px solid var(--lu-purple);
     color: var(--lu-purple);
     font-weight: 900;
   }

   :global(.paronym-slot.filled) {
     border-bottom-color: var(--lu-green);
     color: var(--lu-state-correct-fg);
   }

   :global(.paronym-feedback) {
     margin: 0;
     padding: 0.85rem 0.95rem;
     border-radius: 8px;
     font-weight: 800;
     line-height: 1.45;
   }

   :global(.paronym-feedback p) {
     margin: 0;
   }

   :global(.paronym-feedback.correct) {
     background: var(--lu-state-correct-bg);
     color: var(--lu-state-correct-fg);
   }

   :global(.paronym-feedback.wrong) {
     background: var(--lu-state-wrong-bg);
     color: var(--lu-state-wrong-fg);
   }

   :global(.mc-q) {
     margin: 0 0 0.3rem;
     color: var(--lu-text);
     font-size: 1.5rem;
     font-weight: 900;
   }

   /* Form/drill prompt: question + grammatical descriptor in one text flow. */
   :global(.mc-q .mc-descriptor) {
     font-weight: 700;
     color: var(--lu-text-muted);
   }

   :global(.mc-sub) {
     margin: 0 0 0.3rem;
     color: var(--lu-text-muted);
   }

   :global(.mc-options) {
     display: grid;
     grid-template-columns: 1fr;
     gap: 0.7rem;
   }

   :global(.mc-opt) {
     display: flex;
     align-items: center;
     gap: 12px;
     min-height: 56px;
     padding: 12px 16px;
     border-radius: 12px;
     font-size: 1rem;
     font-weight: 800;
     text-align: left;
     transition: border-color 0.12s, background 0.12s, transform 0.1s;
   }

   :global(.mc-opt:hover:not(:disabled)) {
     border-color: var(--lu-primary);
     transform: translateX(2px);
   }

   :global(.mc-key) {
     width: 26px;
     height: 26px;
     display: grid;
     place-items: center;
     flex-shrink: 0;
     border: 1px solid var(--lu-border);
     border-radius: 7px;
     color: var(--lu-text-muted);
     font-size: 0.8rem;
     font-weight: 900;
   }

   /*
    * #6620: the learner's own pick must be visually distinct even before/instead
    * of the correct/wrong verdict — `.selected` alone (borderless-primary outline)
    * is what a mid-click state or a non-graded pick renders as; `.correct`/`.wrong`
    * always co-occur with `.selected` once the item is locked (see mcOptionAttrs).
    */
   :global(.mc-opt.selected) {
     border-color: var(--lu-primary);
     box-shadow: 0 0 0 2px color-mix(in srgb, var(--lu-primary) 35%, transparent);
   }

   :global(.mc-opt.correct) {
     border-color: var(--lu-green);
     background: var(--lu-state-correct-bg);
     color: var(--lu-state-correct-fg);
     box-shadow: none;
   }

   :global(.mc-opt.correct .mc-key) {
     border-color: var(--lu-green);
     color: var(--lu-state-correct-fg);
   }

   :global(.mc-opt.wrong) {
     border-color: var(--lu-red);
     background: var(--lu-state-wrong-bg);
     color: var(--lu-state-wrong-fg);
     box-shadow: none;
   }

   :global(.mc-opt.wrong .mc-key) {
     border-color: var(--lu-red);
     color: var(--lu-state-wrong-fg);
   }

   :global(.cz-task) {
     margin: 0 0 -0.1rem;
     color: var(--lu-text-muted);
     font-size: 0.92rem;
     font-weight: 700;
   }

   :global(.cz-sentence) {
     margin: 0;
     padding: 1.4rem 1.5rem;
     border: 1px solid var(--lu-border);
     border-radius: 14px;
     background: var(--lu-surface-raised);
     box-shadow: var(--lu-shadow);
     color: var(--lu-text);
     font-size: 1.45rem;
     font-weight: 700;
     line-height: 1.6;
   }

   :global(.cz-blank) {
     display: inline-flex;
     align-items: center;
     justify-content: center;
     min-width: 96px;
     padding: 0 10px;
     margin: 0 4px;
     border-bottom: 3px solid var(--lu-primary);
     color: var(--lu-primary);
     font-weight: 900;
   }

   :global(.cz-blank.filled) {
     border-bottom-color: var(--lu-green);
     color: var(--lu-state-correct-fg);
   }

   :global(.cz-blank.bad),
