     margin: 0.3rem 0 0;
     color: var(--lu-text-muted);
     font-size: 0.86rem;
     font-style: italic;
     line-height: 1.25;
     display: -webkit-box;
     -webkit-line-clamp: 2;
     -webkit-box-orient: vertical;
     overflow: hidden;
