   :global(.k3-session) {
     display: grid;
     gap: 0.35rem;
     padding: 0.6rem 0.75rem;
     border: 1px solid color-mix(in srgb, var(--lu-primary) 28%, var(--lu-border));
     border-radius: 14px;
     background:
       linear-gradient(
         165deg,
         color-mix(in srgb, var(--lu-primary) 8%, var(--lu-surface-raised)) 0%,
         var(--lu-surface-raised) 55%
       );
     box-shadow: var(--lu-shadow);
   }
   /*
    * D4 (design delta 2026-07-26): one card, three stacked rows — pills, then the
    * estimate (its own row, right-aligned, ellipsis rather than card overflow),
    * then the single dominant action. The estimate previously shared a flex row
    * with the pills via `justify-content: space-between`; squeezed into the
    * ~340px right-hand desktop column (`.k3-session` grid-area) that pushed the
    * estimate text outside the card border — confirmed live.
    */
   :global(.k3-session-overview) {
     display: flex;
     flex-direction: column;
     align-items: stretch;
     gap: 0.3rem;
   }
   /*
    * #6544: compact above-fold deck chip. Closed height must stay small so the
    * Start/Resume CTAs clear HARD-1/HARD-2 at 1366×768; the full Drive/Manage
    * panel remains folded below the mode grid (#6336).
    */
   :global(.k3-active-deck) {
     display: flex;
     flex-wrap: wrap;
     align-items: center;
     gap: 0.4rem 0.5rem;
     min-width: 0;
