     flex-direction: column;
     gap: 0.35rem;
     width: 100%;
     padding: 0.45rem;
     border: 1px solid var(--lu-border);
     border-radius: 12px;
     background: var(--lu-surface);
   }
   :global(.k3-active-deck-menu button) {
     display: flex;
     align-items: center;
     justify-content: flex-start;
     min-height: 48px;
     padding: 0 0.75rem;
