     flex-wrap: nowrap;
     flex-shrink: 0;
     gap: 0.5rem;
   }
   :global(.k3-session-budgets button) {
     min-height: 44px;
     padding: 0 0.85rem;
   }
   :global(.k3-session-budgets button.active) {
     border-color: var(--lu-primary);
     background: var(--lu-primary);
     color: var(--lu-on-primary);
   }
   /*
    * Primary Daily/Start CTA (#5502): `.btn-accent` is not a global style, so the
    * session primary used to render as a generic surface button. Force a distinct
    * primary treatment that stays readable in light/dark without hunting.
    */
   :global(.lexicon-practice button.k3-session-primary) {
     display: inline-flex;
     align-items: center;
     justify-content: center;
     gap: 0.35rem;
     min-height: 46px;
     width: 100%;
     padding: 0 1rem;
     border: 1px solid var(--lu-primary);
     border-radius: 12px;
     background: var(--lu-primary);
     color: var(--lu-on-primary);
     font-size: 1.05rem;
     font-weight: 900;
     letter-spacing: 0.01em;
     box-shadow:
       0 1px 0 color-mix(in srgb, var(--lu-on-primary) 18%, transparent) inset,
       0 4px 14px color-mix(in srgb, var(--lu-primary) 32%, transparent);
   }
   :global(.lexicon-practice button.k3-session-primary:hover),
   :global(.lexicon-practice button.k3-session-primary:focus-visible) {
     border-color: var(--lu-primary);
     background: var(--lu-primary);
     color: var(--lu-on-primary);
     filter: brightness(1.06);
     outline: none;
     box-shadow:
       0 0 0 3px var(--lu-state-active),
       0 6px 18px color-mix(in srgb, var(--lu-primary) 38%, transparent);
   }
   :global(.lexicon-practice button.k3-session-primary:disabled) {
     opacity: 0.72;
     filter: none;
     cursor: wait;
   }
   /*
    * D5: "Почати наново" / "Start over" is a secondary, DANGER-outline action — it
    * discards the resumable session's progress via `clearPracticeSessionSnapshots()`
    * — never underlined link-text (that reads as a low-stakes secondary link, the
    * opposite of what a progress-discarding reset should signal).
    */
   :global(.lexicon-practice button.k3-session-reset) {
     justify-self: stretch;
     min-height: 44px;
     width: 100%;
     padding: 0 1rem;
     border: 1px solid var(--lu-state-wrong-fg, #b91c1c);
     background: transparent;
     color: var(--lu-state-wrong-fg, #b91c1c);
     font-weight: 800;
