   :global(.lexicon-practice button.k3-session-reset:focus-visible) {
     border-color: var(--lu-state-wrong-fg, #b91c1c);
     background: var(--lu-state-wrong-bg);
     color: var(--lu-state-wrong-fg, #b91c1c);
     box-shadow: none;
     outline: 2px solid var(--lu-state-wrong-fg, #b91c1c);
     outline-offset: 2px;
   }

