   :global(.daily-deck-atlas-link) {
     color: var(--lu-primary);
     font-weight: 800;
     text-decoration: none;
   }
   :global(.daily-deck-voice-slot) {
     color: var(--lu-text-muted);
     font-size: 0.85rem;
   }
   :global(.daily-deck-example) {
     margin: 0.45rem 0 0;
     color: var(--lu-text);
     font-size: 0.95rem;
     line-height: 1.35;
   }
   :global(.daily-deck-example-en) {
     display: block;
     margin-top: 0.2rem;
     color: var(--lu-text-muted);
     font-size: 0.88em;
   }
   :global(.daily-deck-origin) {
     margin: 0.55rem 0 0;
     color: var(--lu-text-muted);
     font-size: 0.88rem;
     font-style: italic;
     line-height: 1.35;
   }
   :global(.daily-deck-origin strong) {
     font-style: normal;
     font-weight: 600;
   }
   :global(.daily-deck-details) {
     border: 1px solid var(--lu-border);
     border-radius: 10px;
     background: var(--lu-surface);
   }
   :global(.daily-deck-details summary) {
     display: flex;
     align-items: center;
     justify-content: space-between;
     gap: 0.75rem;
     min-height: 48px;
     padding: 0 1rem;
     cursor: pointer;
     font-weight: 800;
   }
   :global(.daily-deck-counters) {
     display: flex;
     flex-wrap: wrap;
     gap: 0.4rem;
   }
   :global(.daily-deck-counters .counter) {
     display: inline-flex;
     align-items: center;
     gap: 0.25rem;
     min-width: 1.5rem;
     height: 1.5rem;
     padding: 0 0.55rem;
     border-radius: 999px;
     font-size: 0.72rem;
     font-weight: 900;
     white-space: nowrap;
   }
   :global(.daily-deck-counters .counter.due) {
     background: var(--lu-yellow-dark);
     color: var(--lu-on-primary);
   }
   :global(.daily-deck-counters .counter.new) {
     background: var(--lu-blue);
     color: var(--lu-on-primary);
   }
   :global(.daily-deck-counters .counter.done) {
     background: var(--lu-green);
     color: var(--lu-on-primary);
   }
   :global(.daily-deck-rows) {
     margin: 0;
     padding: 0 1rem 1rem;
     list-style: none;
   }
   :global(.daily-deck-row) {
     border-radius: 8px;
   }
   :global(.daily-deck-row.state-done) {
     background: var(--lu-state-correct-bg);
   }
   :global(.daily-deck-row-link) {
     display: grid;
     grid-template-columns: auto auto minmax(0, 1fr) auto;
     align-items: start;
     gap: 0.75rem;
     min-height: 52px;
     padding: 0.5rem 0.75rem;
     color: var(--lu-text);
     text-decoration: none;
   }
   :global(.row-marker) {
     display: inline-flex;
     align-items: center;
     justify-content: center;
     min-width: 1.5rem;
     min-height: 1.5rem;
     border: 1px solid var(--row-accent);
     border-radius: 0.35rem;
     color: var(--row-accent);
     font-weight: 900;
   }
   :global(.row-number) {
     color: var(--lu-text-muted);
     font-size: 0.85rem;
   }
   :global(.row-lemma) {
     display: block;
     font-weight: 800;
   }
   :global(.row-identity) {
     min-width: 0;
   }
   :global(.row-gloss) {
     display: block;
     color: var(--lu-text-muted);
     font-size: 0.9rem;
   }
   :global(.row-why) {
     display: block;
     margin-top: 0.15rem;
     color: var(--lu-text-muted);
     font-size: 0.78rem;
     font-weight: 700;
     line-height: 1.35;
   }
   :global(.row-status) {
     font-size: 0.75rem;
     font-weight: 800;
     text-transform: uppercase;
     letter-spacing: 0.03em;
   }
   :global(.daily-deck-row.state-due .row-status) {
     color: var(--lu-yellow-dark);
   }
   :global(.daily-deck-row.state-new .row-status) {
     color: var(--lu-blue);
   }
   :global(.daily-deck-row.state-done .row-lemma) {
     font-weight: 600;
   }
   :global(.daily-deck-row.state-done .row-marker),
   :global(.daily-deck-row.state-done .row-status) {
     color: var(--lu-green);
   }

   :global(.k3-secondary) {
     display: grid;
     gap: 1rem;
   }
   :global(.k3-secondary .lexicon-weak-areas) {
     padding: 0.85rem 0 0;
     border-top: 1px solid var(--lu-border);
   }

   :global(.k3-modes) {
     display: grid;
     gap: 0.75rem;
     padding: 0.85rem 0;
     border-top: 1px solid var(--lu-border);
   }
   :global(.k3-modes h2) {
     margin: 0;
     font-size: 1rem;
     font-weight: 900;
     text-transform: uppercase;
     letter-spacing: 0.04em;
   }
   :global(.k3-mode-detail) {
     min-height: 2.75rem;
     margin: 0;
     color: var(--lu-text-muted);
     font-size: 0.92rem;
     line-height: 1.5;
   }
   :global(.k3-mode-grid) {
     display: grid;
     grid-template-columns: repeat(2, minmax(0, 1fr));
     gap: 0.75rem;
   }
   @media (min-width: 1000px) {
     :global(.k3-mode-grid) {
       grid-template-columns: repeat(4, minmax(0, 1fr));
     }
   }
   :global(.k3-mode-card) {
     position: relative;
     display: flex;
     min-height: 48px;
     flex-direction: column;
     justify-content: center;
     gap: 0.25rem;
     padding: 0.75rem 1rem;
     border: 1px solid var(--lu-border);
     border-radius: 10px;
     background: var(--lu-surface);
     color: var(--lu-text);
     text-align: left;
     cursor: pointer;
   }
   :global(.k3-mode-card:hover),
   :global(.k3-mode-card:focus-visible) {
     border-color: var(--lu-primary);
     outline: none;
     box-shadow: 0 0 0 3px var(--lu-state-active);
   }
   :global(.k3-mode-card[data-mode-empty='true']) {
     opacity: 0.55;
     cursor: not-allowed;
   }
   :global(.k3-mode-card:disabled:hover) {
     border-color: var(--lu-border);
     box-shadow: none;
   }
   :global(.k3-mode-title) {
     font-size: 1rem;
     font-weight: 900;
   }
   :global(.k3-mode-step) {
     color: var(--lu-text-muted);
     font-size: 0.72rem;
     font-weight: 900;
     letter-spacing: 0.04em;
     text-transform: uppercase;
   }
   /* P0-1: the description now lives on every card, not only the shared hover line. */
   :global(.k3-mode-desc) {
     margin: 0.15rem 0 0;
     color: var(--lu-text-muted);
     font-size: 0.8rem;
     font-weight: 600;
     line-height: 1.35;
     text-transform: none;
   }
   /* P0-3: an explicit, honest "no exercises yet" state instead of a silent tap-and-fail. */
   :global(.k3-mode-empty-note) {
     margin: 0.15rem 0 0;
     color: var(--lu-text-muted);
     font-size: 0.72rem;
     font-weight: 900;
     text-transform: uppercase;
     letter-spacing: 0.03em;
   }
   :global(.k3-mode-count) {
     position: absolute;
     top: 0.5rem;
     right: 0.6rem;
     min-width: 1.4em;
     padding: 0.05rem 0.4rem;
     border-radius: 999px;
     background: var(--lu-surface-raised);
     color: var(--lu-text-muted);
     font-size: 0.72rem;
     font-weight: 900;
     text-align: center;
   }
   :global(.k3-mode-card[data-mode-empty='true'] .k3-mode-count) {
     color: var(--lu-text-muted);
     background: transparent;
     border: 1px solid var(--lu-border);
   }

   /* Chunk 5 — generalized form rail and N-vowel stress */
   :global(.practice-form-rail) {
     display: grid;
     gap: 0.6rem;
     padding: 0.9rem 1rem;
     border: 1px solid var(--lu-border);
     border-radius: 10px;
     background: var(--lu-surface-raised);
   }

   :global(.practice-form-rail-row) {
     display: flex;
     align-items: center;
     gap: 0.75rem;
   }

   :global(.practice-form-rail-cell) {
     display: grid;
     gap: 0.15rem;
     flex: 1 1 0;
     min-width: 0;
   }

   :global(.rail-cell-label) {
     color: var(--lu-text-muted);
     font-size: 0.72rem;
     font-weight: 900;
     letter-spacing: 0.04em;
     text-transform: uppercase;
   }

   :global(.rail-cell-value) {
     color: var(--lu-text);
     font-size: 1.15rem;
     font-weight: 800;
     line-height: 1.35;
     word-break: break-word;
   }

   :global(.practice-form-rail-separator) {
     color: var(--lu-text-muted);
     font-size: 1.1rem;
     font-weight: 900;
   }

   :global(.practice-form-rail-status) {
     margin: 0;
     font-weight: 900;
   }

   :global(.practice-form-rail.verdict-correct) {
     border-color: var(--lu-green);
     background: var(--lu-state-correct-bg);
   }
   :global(.practice-form-rail.verdict-correct .practice-form-rail-status),
   :global(.practice-form-rail.verdict-correct .rail-cell-value) {
     color: var(--lu-state-correct-fg);
   }

   :global(.practice-form-rail.verdict-wrong) {
     border-color: var(--lu-red);
     background: var(--lu-state-wrong-bg);
   }
   :global(.practice-form-rail.verdict-wrong .practice-form-rail-status),
   :global(.practice-form-rail.verdict-wrong .rail-cell-value) {
     color: var(--lu-state-wrong-fg);
   }

   :global(.practice-form-rail.verdict-calque) {
     border-color: color-mix(in srgb, var(--lu-orange) 50%, transparent);
     background: var(--lu-orange-light);
   }
   :global(.practice-form-rail.verdict-calque .practice-form-rail-status),
   :global(.practice-form-rail.verdict-calque .rail-cell-value) {
     color: var(--lu-orange);
   }

   :global(.lexicon-stress) {
     display: grid;
     gap: 1rem;
+    /* #6716: keep rows content-sized instead of stretching to fill the stage's
+       420px min-height, which inflated the prompt box ~110px and pushed the
+       stressed-vowel tiles ~150px below the question. Same rhythm as choice. */
+    align-content: start;
   }

   :global(.practice-stress-word) {
     display: flex;
     flex-wrap: wrap;
     align-items: center;
     gap: 0.1rem;
     margin: 0;
     padding: 1.25rem 1.5rem;
     border: 1px solid var(--lu-border);
     border-radius: 14px;
     background: var(--lu-surface-raised);
     box-shadow: var(--lu-shadow);
     color: var(--lu-text);
     font-size: 1.8rem;
     font-weight: 700;
     line-height: 1.6;
   }

   :global(.stress-vowel) {
     position: relative;
     min-width: 48px;
     min-height: 48px;
     padding: 0.2rem 0.5rem;
     border: 2px solid var(--lu-border);
     border-radius: 8px;
     background: var(--lu-surface);
     color: var(--lu-primary);
     font: inherit;
     font-size: 1.35em;
     font-weight: 900;
     cursor: pointer;
   }

   :global(.stress-vowel-key) {
     position: absolute;
     top: 2px;
     right: 4px;
     color: var(--lu-text-muted);
     font-size: 0.65rem;
     font-weight: 900;
   }

   :global(.stress-vowel:hover:not(:disabled)) {
     border-color: var(--lu-primary);
     background: var(--lu-state-active);
   }

   :global(.stress-vowel:focus-visible) {
     border-color: var(--lu-primary);
     outline: 2px solid var(--lu-primary);
     outline-offset: 2px;
   }

   :global(.stress-vowel.selected) {
     border-color: var(--lu-primary);
     background: var(--lu-primary);
     color: var(--lu-on-primary);
   }

   :global(.stress-vowel.correct) {
     border-color: var(--lu-green);
     background: var(--lu-state-correct-bg);
     color: var(--lu-state-correct-fg);
   }

   :global(.stress-vowel.wrong) {
     border-color: var(--lu-red);
     background: var(--lu-state-wrong-bg);
     color: var(--lu-state-wrong-fg);
   }

   :global(.practice-stress-verdict) {
     margin: 0;
     font-size: 1.5rem;
     font-weight: 900;
     text-align: center;
   }
   :global(.practice-stress-verdict.correct) {
     color: var(--lu-green);
   }
   :global(.practice-stress-verdict.wrong) {
     color: var(--lu-red);
   }

   /*
    * #6620: `.zno-practice*` had zero CSS — selected/correct/wrong classes were
    * dead, and the stem rendered as a flat `pre-wrap` wall of text. This block
    * gives ZnoPractice the same option/verdict language as `.mc-opt` (shared
    * tokens, same min-height, same green/red states) plus a dedicated passage
    * card for multi-line reading-comprehension stems.
    */
   :global(.zno-practice) {
     display: grid;
     gap: 1rem;
     color: var(--lu-text);
   }

   :global(.zno-practice-decks) {
     display: grid;
     grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
     gap: 0.75rem;
   }

   :global(.zno-practice-decks button) {
     display: flex;
     flex-direction: column;
     align-items: flex-start;
     gap: 0.2rem;
     min-height: 64px;
     padding: 0.75rem 1rem;
     text-align: left;
   }

   :global(.zno-practice-item) {
     display: grid;
     gap: 0.85rem;
     max-width: 760px;
   }

   :global(.zno-practice-title) {
     margin: 0;
     color: var(--lu-text-muted);
     font-size: 0.82rem;
     font-weight: 900;
     letter-spacing: 0.03em;
     text-transform: uppercase;
   }

   :global(.zno-practice-thin) {
     margin: 0;
     color: var(--lu-orange);
     font-size: 0.85rem;
     font-weight: 800;
   }

   :global(.zno-practice-instruction) {
     margin: 0;
     color: var(--lu-text);
     font-size: 1.2rem;
     font-weight: 850;
     line-height: 1.4;
   }

   :global(.zno-practice-passage) {
     margin: 0;
     max-width: 68ch;
     padding: 1.1rem 1.3rem;
     border: 1px solid var(--lu-border);
     border-radius: 14px;
     background: var(--lu-surface-raised);
     box-shadow: var(--lu-shadow);
     color: var(--lu-text);
     font-size: 1.05rem;
     line-height: 1.6;
   }

   :global(.zno-practice-options) {
     display: grid;
     gap: 0.6rem;
     margin: 0;
     padding: 0;
     list-style: none;
   }

   :global(.zno-practice-option) {
     display: flex;
     align-items: center;
     gap: 12px;
     width: 100%;
     min-height: 56px;
     padding: 12px 16px;
     border: 1px solid var(--lu-border);
     border-radius: 12px;
     background: var(--lu-surface);
     color: var(--lu-text);
     font: inherit;
     font-size: 1rem;
     font-weight: 700;
     text-align: left;
     cursor: pointer;
     transition: border-color 0.12s, background 0.12s, transform 0.1s;
   }

   :global(.zno-practice-option:hover:not(:disabled)) {
     border-color: var(--lu-primary);
     transform: translateX(2px);
   }

   :global(.zno-practice-option:disabled) {
     cursor: default;
   }

   :global(.zno-practice-option-key) {
     display: grid;
     place-items: center;
     width: 28px;
     height: 28px;
     flex-shrink: 0;
     border: 1px solid var(--lu-border);
     border-radius: 8px;
     color: var(--lu-text-muted);
     font-size: 0.85rem;
     font-weight: 900;
   }

   :global(.zno-practice-option-text) {
     line-height: 1.45;
   }

   :global(.zno-practice-mark-underline) {
     text-decoration: underline;
     text-decoration-thickness: 2px;
     text-underline-offset: 0.15em;
     font-weight: 900;
   }

   :global(.zno-practice-mark-bold) {
     font-weight: 900;
   }

   :global(.zno-practice-option.selected) {
     border-color: var(--lu-primary);
     box-shadow: 0 0 0 2px color-mix(in srgb, var(--lu-primary) 35%, transparent);
   }

   :global(.zno-practice-option.correct) {
     border-color: var(--lu-green);
     background: var(--lu-state-correct-bg);
     color: var(--lu-state-correct-fg);
     box-shadow: none;
   }

   :global(.zno-practice-option.correct .zno-practice-option-key) {
     border-color: var(--lu-green);
     color: var(--lu-state-correct-fg);
   }

   :global(.zno-practice-option.wrong) {
     border-color: var(--lu-red);
     background: var(--lu-state-wrong-bg);
     color: var(--lu-state-wrong-fg);
     box-shadow: none;
   }

   :global(.zno-practice-option.wrong .zno-practice-option-key) {
     border-color: var(--lu-red);
     color: var(--lu-state-wrong-fg);
   }

   :global(.zno-practice-verdict) {
     margin: 0;
     padding: 0.75rem 0.9rem;
     border-radius: 10px;
     font-weight: 900;
   }

   :global(.zno-practice-verdict.correct) {
     background: var(--lu-state-correct-bg);
     color: var(--lu-state-correct-fg);
   }

   :global(.zno-practice-verdict.wrong) {
     background: var(--lu-state-wrong-bg);
     color: var(--lu-state-wrong-fg);
   }

   :global(.zno-practice-attribution) {
     margin: 0;
     color: var(--lu-text-muted);
     font-size: 0.82rem;
   }

   :global(.zno-practice-actions) {
     display: flex;
     flex-wrap: wrap;
     gap: 0.6rem;
   }

   :global(.zno-practice-next) {
     border-color: var(--lu-primary);
     background: var(--lu-primary);
     color: var(--lu-on-primary);
   }

   @media (max-width: 560px) {
     :global(.zno-practice-passage) {
       max-width: none;
     }
   }
 </style>

