import { chromium } from 'playwright';

const BASE = 'http://localhost:4322/words-of-the-day/practice/';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1366, height: 768 } });
await page.goto(BASE, { waitUntil: 'networkidle' });
await page.waitForSelector('button.k3-mode-card[data-mode="stress"]', { timeout: 30000 });
await page.click('button.k3-mode-card[data-mode="stress"]');
await page.waitForSelector('[data-testid="practice-stress"]', { timeout: 30000 });

const results = {};
const measure = () => page.evaluate(() => {
  const prompt = document.querySelector('[data-testid="practice-form-prompt"]');
  const word = document.querySelector('.practice-stress-word');
  const pr = prompt.getBoundingClientRect();
  const wr = word.getBoundingClientRect();
  const cs = getComputedStyle(prompt);
  return {
    promptTop: Math.round(pr.top), promptBottom: Math.round(pr.bottom), promptHeight: Math.round(pr.height),
    wordTop: Math.round(wr.top),
    gapPromptBottomToWordTop: Math.round(wr.top - pr.bottom),
    alignSelf: cs.alignSelf,
    display: cs.display,
  };
});

results.baseline = await measure();

// Experiment 1: prompt align-self start
await page.addStyleTag({ content: '.lexicon-stress > .lexicon-choice-prompt { align-self: start; }' });
results.alignSelfStart = await measure();
await page.removeStyleTag((await page.$$('style')).pop()?.evaluate ? null : null);

// Experiment 2: keep grid, add explicit align-items
await page.addStyleTag({ content: '.lexicon-stress { align-items: start; }' });
results.stressAlignStart = await measure();

console.log(JSON.stringify(results, null, 2));
await browser.close();

