const probe = () => page.evaluate(() => {
  const q = (s) => document.querySelector(s);
  const rect = (el) => { if (!el) return null; const r = el.getBoundingClientRect(); return { top: Math.round(r.top), bottom: Math.round(r.bottom), height: Math.round(r.height) }; };
  const cs = (el) => { if (!el) return null; const s = getComputedStyle(el); return { display: s.display, height: s.height, minHeight: s.minHeight, alignContent: s.alignContent, alignItems: s.alignItems, gridTemplateRows: s.gridTemplateRows, gridAutoRows: s.gridAutoRows, gridTemplateColumns: s.gridTemplateColumns }; };
  return {
    stage: { rect: rect(q('.lexicon-practice-stage')), cs: cs(q('.lexicon-practice-stage')) },
    stress: { rect: rect(q('.lexicon-stress')), cs: cs(q('.lexicon-stress')) },
    prompt: { rect: rect(q('[data-testid="practice-form-prompt"]')), cs: cs(q('[data-testid="practice-form-prompt"]')) },
    practiceStress: { rect: rect(q('.practice-stress')), cs: cs(q('.practice-stress')) },
    word: { rect: rect(q('.practice-stress-word')), cs: cs(q('.practice-stress-word')) },
  };
});

const out = {};
out.baseline = await probe();
await page.addStyleTag({ content: '.lexicon-stress { align-items: start; }' });
out.alignItemsStart = await probe();
await page.addStyleTag({ content: '.lexicon-stress { align-content: start; }' });
out.alignContentStart = await probe();
await page.addStyleTag({ content: '.lexicon-practice-stage { align-items: start; }' });
out.stageAlignStart = await probe();
console.log(JSON.stringify(out, null, 2));
await browser.close();

