import { chromium } from 'playwright';

const BASE = 'http://localhost:4322/words-of-the-day/practice/';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1366, height: 768 } });
await page.goto(BASE, { waitUntil: 'networkidle' });
await page.waitForSelector('button.k3-mode-card[data-mode="stress"]', { timeout: 30000 });
await page.click('button.k3-mode-card[data-mode="stress"]');
await page.waitForSelector('[data-testid="practice-stress"]', { timeout: 30000 });

const probe = () => page.evaluate(() => {
  const q = (s) => document.querySelector(s);
  const rect = (el) => { if (!el) return null; const r = el.getBoundingClientRect(); return { top: Math.round(r.top), bottom: Math.round(r.bottom), height: Math.round(r.height) }; };
  const prompt = q('[data-testid="practice-form-prompt"]');
  const word = q('.practice-stress-word');
  const stress = q('.lexicon-stress');
  return {
    promptRect: rect(prompt),
    wordRect: rect(word),
    stressRect: rect(stress),
    gapTextToTile: word && prompt ? Math.round(word.getBoundingClientRect().top - prompt.getBoundingClientRect().bottom) : null,
    stressCS: getComputedStyle(stress).cssText.slice(0, 200),
  };
});

const run = async (label, css) => {
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForSelector('button.k3-mode-card[data-mode="stress"]', { timeout: 30000 });
  await page.click('button.k3-mode-card[data-mode="stress"]');
  await page.waitForSelector('[data-testid="practice-stress"]', { timeout: 30000 });
  if (css) await page.addStyleTag({ content: css });
  const p = await probe();
  console.log(label, JSON.stringify(p));
};

await run('BASELINE', null);
await run('stress align-content:start', '.lexicon-stress { align-content: start; }');
await run('stress align-items:start', '.lexicon-stress { align-items: start; }');
await run('stress align-self:start on prompt only', '.lexicon-stress > .lexicon-choice-prompt { align-self: start; }');
await run('stage align-items:start', '.lexicon-practice-stage { align-items: start; }');
await run('stress justify... none', null);

await browser.close();

