import { chromium } from 'playwright';

const BASE = 'http://localhost:4322/words-of-the-day/practice/';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1366, height: 768 } });
await page.goto(BASE, { waitUntil: 'networkidle' });
await page.waitForSelector('button.k3-mode-card[data-mode="choice"]', { timeout: 30000 });
await page.click('button.k3-mode-card[data-mode="choice"]');
await page.waitForSelector('.lexicon-choice .lexicon-option-list', { timeout: 30000 });

const out = await page.evaluate(() => {
  const stage = document.querySelector('.lexicon-practice-stage');
  const choice = document.querySelector('.lexicon-choice');
  const prompt = choice.querySelector('.lexicon-choice-prompt');
  const options = choice.querySelector('.lexicon-option-list');
  const pr = prompt.getBoundingClientRect();
  const or = options.getBoundingClientRect();
  const s = getComputedStyle(prompt);
  return {
    stage: (() => { const r = stage.getBoundingClientRect(); return { top: Math.round(r.top), height: Math.round(r.height), cs: getComputedStyle(stage).height }; })(),
    choice: (() => { const r = choice.getBoundingClientRect(); return { top: Math.round(r.top), bottom: Math.round(r.bottom), height: Math.round(r.height), cs: getComputedStyle(choice).height }; })(),
    prompt: { top: Math.round(pr.top), bottom: Math.round(pr.bottom), height: Math.round(pr.height), font: s.fontSize, lh: s.lineHeight },
    options: { top: Math.round(or.top), height: Math.round(or.height), count: options.children.length },
    gapPromptToOptions: Math.round(or.top - pr.bottom),
  };
});
console.log(JSON.stringify(out, null, 2));
await browser.close();

