import { chromium } from 'playwright';

const BASE = 'http://localhost:4322/words-of-the-day/practice/';
const OUT = '/private/var/folders/pd/wvj52r1j3bd4z9y3dfc2k4180000gn/T/learn-ukrainian/6716-stress-gap/opencode';
const browser = await chromium.launch();

async function setup(view) {
  const page = await browser.newPage({ viewport: view });
  await page.goto(BASE, { waitUntil: 'networkidle' });
  await page.waitForSelector('button.k3-mode-card[data-mode="stress"]', { timeout: 30000 });
  await page.click('button.k3-mode-card[data-mode="stress"]');
  await page.waitForSelector('[data-testid="practice-stress"]', { timeout: 30000 });
  return page;
}

async function measure(page) {
  return page.evaluate(() => {
    const q = (s) => document.querySelector(s);
    const rect = (el) => { if (!el) return null; const r = el.getBoundingClientRect(); return { top: Math.round(r.top), bottom: Math.round(r.bottom), height: Math.round(r.height) }; };
    const prompt = q('[data-testid="practice-form-prompt"]');
    const word = q('.practice-stress-word');
    const rating = q('.lexicon-rating-bar');
    return {
      prompt: rect(prompt),
      word: rect(word),
      rating: rect(rating),
      promptTextToTile: prompt && word ? Math.round(word.getBoundingClientRect().top - prompt.getBoundingClientRect().bottom) : null,
    };
  });
}

const results = {};

// Desktop baseline
{
  const page = await setup({ width: 1366, height: 768 });
  results.desktopBaseline = await measure(page);
  await page.screenshot({ path: `${OUT}/desktop-baseline.png` });
  // answer
  await page.click('button.stress-vowel');
  await page.waitForSelector('[data-testid="practice-stress-verdict"]', { timeout: 10000 });
  results.desktopBaselineAnswered = await measure(page);
  await page.screenshot({ path: `${OUT}/desktop-baseline-answered.png` });
  await page.close();
}

// Desktop fix
{
  const page = await setup({ width: 1366, height: 768 });
  await page.addStyleTag({ content: '.lexicon-stress { align-content: start; }' });
  results.desktopFix = await measure(page);
  await page.screenshot({ path: `${OUT}/desktop-fix.png` });
  await page.click('button.stress-vowel');
  await page.waitForSelector('[data-testid="practice-stress-verdict"]', { timeout: 10000 });
  results.desktopFixAnswered = await measure(page);
  await page.screenshot({ path: `${OUT}/desktop-fix-answered.png` });
  await page.close();
}

// Narrow baseline + fix
{
  const page = await setup({ width: 390, height: 844 });
  results.narrowBaseline = await measure(page);
  await page.screenshot({ path: `${OUT}/narrow-baseline.png` });
  await page.close();
}
{
  const page = await setup({ width: 390, height: 844 });
  await page.addStyleTag({ content: '.lexicon-stress { align-content: start; }' });
  results.narrowFix = await measure(page);
  await page.screenshot({ path: `${OUT}/narrow-fix.png` });
  await page.close();
}

console.log(JSON.stringify(results, null, 2));
await browser.close();

